Construct a counterexample trace for this RFS module and property:
```rfs
module m {
  enum State { A, B }
  initial A
  event Go
  transition A on Go { next B; }
}
prop stays_a : always (state == A) ;
```

What is the state-space size of this RFS module?
```rfs
module m {
  enum State { A, B, C }
  initial A
  var mode: Mode init Mode::Normal
  enum Mode { Normal, Fast, Error }
  var flag: bool init false
}
```

Give a model-checking plan for this RFS module:
```rfs
module timeout {
  enum State { Idle, Waiting }
  initial Idle
  event Req
  event Ack
  event Tick
  output Retry
  var timer: bit<3> init 3
  transition Idle on Req { next Waiting; set timer = 3; }
  transition Waiting on Ack { next Idle; }
  transition Waiting on Tick where timer > 0 { next Waiting; set timer = timer - 1; emit Retry; }
  transition Waiting on Tick where timer == 0 { next Idle; }
}
```
